#!/usr/bin/env node
/**
 * apply-lt-names-fixes.mjs
 *
 * Idempotent script that applies curated fixes from data/lt-names-fixes.json
 * to data/lt-names.json. Adds an _appliedFix marker to each modified entry
 * so re-runs are safe.
 *
 * Usage:
 *   node scripts/apply-lt-names-fixes.mjs           # dry-run (default)
 *   node scripts/apply-lt-names-fixes.mjs --apply   # actually write
 *
 * Generated by lt-names audit (2026-05-24).
 */

import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(__dirname, '..');
const LT_NAMES_PATH = resolve(ROOT, 'data', 'lt-names.json');
const FIXES_PATH = resolve(ROOT, 'data', 'lt-names-fixes.json');
const BACKUP_PATH = resolve(ROOT, 'data', `lt-names.backup.${new Date().toISOString().slice(0, 10)}.json`);

const APPLY = process.argv.includes('--apply');

function log(...args) {
  console.log(...args);
}

function applyFix(entry, fix, genus) {
  // Detect if already applied (idempotency)
  if (entry._appliedFix && entry._appliedFix.action === fix.action) {
    return { changed: false, reason: 'already_applied' };
  }

  const before = JSON.parse(JSON.stringify(entry));
  const changes = [];

  switch (fix.action) {
    case 'drop_synonym': {
      const dropSet = new Set(fix.currentSynonyms || []);
      const newSyn = (entry.ltSynonyms || []).filter((s) => !dropSet.has(s));
      const newAll = (entry.ltAllForms || []).filter((s) => !dropSet.has(s));
      if (newSyn.length !== (entry.ltSynonyms || []).length) {
        entry.ltSynonyms = newSyn;
        entry.ltAllForms = newAll;
        changes.push('synonyms_filtered');
      }
      if (fix.correctConflicts === null && entry.conflicts) {
        entry.conflicts = null;
        changes.push('conflicts_cleared');
      }
      break;
    }

    case 'clear_ltname': {
      if (entry.ltName) {
        entry.ltName = null;
        entry.ltAllForms = (entry.ltAllForms || []).filter((s) => s !== before.ltName);
        changes.push('ltName_cleared');
      }
      break;
    }

    case 'drop_disambig_suffix': {
      const filter = (arr) => (arr || []).filter((s) => !/\((reikšmės|ežeras|miestas|kaimas|asteroidas|žvaigždynas)/i.test(s));
      const newSyn = filter(entry.ltSynonyms);
      const newAll = filter(entry.ltAllForms);
      if (newSyn.length !== (entry.ltSynonyms || []).length) {
        entry.ltSynonyms = newSyn;
        entry.ltAllForms = newAll;
        changes.push('disambig_suffix_dropped');
      }
      break;
    }

    case 'drop_disambig_suffix_and_clear_family': {
      const filter = (arr) => (arr || []).filter((s) => !/\((reikšmės|ežeras|miestas|kaimas|asteroidas|žvaigždynas)/i.test(s));
      const newSyn = filter(entry.ltSynonyms);
      const newAll = filter(entry.ltAllForms);
      if (newSyn.length !== (entry.ltSynonyms || []).length) {
        entry.ltSynonyms = newSyn;
        entry.ltAllForms = newAll;
        changes.push('disambig_suffix_dropped');
      }
      if (entry.ltFamily === 'Nuorodiniai straipsniai') {
        entry.ltFamily = null;
        changes.push('family_cleared');
      }
      break;
    }

    default:
      log(`  WARNING: unknown action "${fix.action}" for ${genus}`);
      return { changed: false, reason: 'unknown_action' };
  }

  if (changes.length === 0) {
    return { changed: false, reason: 'no_diff' };
  }

  entry._appliedFix = {
    at: new Date().toISOString(),
    action: fix.action,
    reason: fix.reason,
    evidence: fix.evidence,
    changes,
  };

  return { changed: true, changes };
}

function applySecondaryFamilyFix(entry, secFix, genus) {
  if (entry._appliedFix && entry._appliedFix.action === 'clear_disambig_family') {
    return { changed: false, reason: 'already_applied' };
  }
  if (entry.ltFamily !== 'Nuorodiniai straipsniai') {
    return { changed: false, reason: 'family_already_clean' };
  }
  const before = entry.ltFamily;
  entry.ltFamily = secFix.correctLtFamily ?? null;
  entry._appliedFix = {
    at: new Date().toISOString(),
    action: 'clear_disambig_family',
    reason: 'ltFamily was Wikipedia disambig category "Nuorodiniai straipsniai", not a taxonomic family',
    note: secFix.note,
    before,
    after: entry.ltFamily,
  };
  return { changed: true, changes: ['family_replaced'] };
}

function main() {
  log(`[apply-lt-names-fixes] mode = ${APPLY ? 'APPLY' : 'DRY-RUN'}`);
  log(`[apply-lt-names-fixes] reading ${LT_NAMES_PATH}`);
  const ltData = JSON.parse(readFileSync(LT_NAMES_PATH, 'utf8'));
  log(`[apply-lt-names-fixes] reading ${FIXES_PATH}`);
  const fixesData = JSON.parse(readFileSync(FIXES_PATH, 'utf8'));

  let primaryApplied = 0;
  let primarySkipped = 0;
  let secondaryApplied = 0;
  let secondarySkipped = 0;
  const notFound = [];

  // Primary fixes
  log('\n--- Primary fixes ---');
  for (const [genus, fix] of Object.entries(fixesData.fixes || {})) {
    const entry = ltData.ltNames[genus];
    if (!entry) {
      notFound.push(genus);
      continue;
    }
    const result = applyFix(entry, fix, genus);
    if (result.changed) {
      primaryApplied++;
      log(`  [APPLIED] ${genus}: ${result.changes.join(', ')}`);
    } else {
      primarySkipped++;
      log(`  [SKIP]    ${genus}: ${result.reason}`);
    }
  }

  // Secondary family-only fixes
  log('\n--- Secondary family-only fixes ---');
  const secFixes = fixesData.secondaryFixesFamilyOnly?.entries || {};
  for (const [genus, secFix] of Object.entries(secFixes)) {
    const entry = ltData.ltNames[genus];
    if (!entry) {
      notFound.push(genus);
      continue;
    }
    const result = applySecondaryFamilyFix(entry, secFix, genus);
    if (result.changed) {
      secondaryApplied++;
      log(`  [APPLIED] ${genus}: family ${secFix.correctLtFamily ? `→ ${secFix.correctLtFamily}` : 'cleared'}`);
    } else {
      secondarySkipped++;
      log(`  [SKIP]    ${genus}: ${result.reason}`);
    }
  }

  log('\n--- Summary ---');
  log(`  Primary fixes applied:   ${primaryApplied}`);
  log(`  Primary fixes skipped:   ${primarySkipped}`);
  log(`  Secondary fixes applied: ${secondaryApplied}`);
  log(`  Secondary fixes skipped: ${secondarySkipped}`);
  if (notFound.length) log(`  Genera not found in lt-names.json: ${notFound.join(', ')}`);

  if (!APPLY) {
    log('\n[DRY-RUN] No file written. Re-run with --apply to persist changes.');
    return;
  }

  // Backup before write
  log(`\n[BACKUP] writing ${BACKUP_PATH}`);
  writeFileSync(BACKUP_PATH, readFileSync(LT_NAMES_PATH));

  // Update top-level metadata
  ltData._lastAuditApplied = {
    at: new Date().toISOString(),
    fixesFile: 'data/lt-names-fixes.json',
    primaryApplied,
    secondaryApplied,
  };

  log(`[WRITE] writing ${LT_NAMES_PATH}`);
  writeFileSync(LT_NAMES_PATH, JSON.stringify(ltData, null, 2));
  log('[DONE] lt-names.json updated.');
}

main();
